size_t index = 0;
while (index < binfo->nbits) {
    size_t word_index = index / (sizeof(bitmap_t) * 8);
    size_t bit_index = index % (sizeof(bitmap_t) * 8);
    bitmap_t mask = static_cast<bitmap_t>(1) << bit_index;
    if ((bitmap[word_index] & mask) == 0) {
        if (std::atomic_compare_exchange_strong(&bitmap[word_index], &bitmap[word_index], bitmap[word_index] | mask)) {
            return index;
        }
    }
    index++;
}
return binfo->nbits;

